// Appends Chemical Waving ids 332-336 and Haircoloring ids 337-381
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/barber-questions.js')

function fmt(q, topic, topic_es) {
  return `  { id: ${q.id}, topic: ${topic}, topic_es: ${topic_es}, psi_topic: ${topic}, psi_topic_es: ${topic_es}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

// Last 5 Chemical Waving & Relaxing (ids 332–336)
const cwT = `"Chemical Waving & Relaxing"`, cwTes = `"Ondulación Química y Alisado"`
const cwQ = [
  { id: 332, question: "Informed consent before a chemical waving or relaxing service requires that the client:", question_es: "El consentimiento informado antes de un servicio de ondulación química o alisado requiere que el cliente:", options: ["Understands the potential risks and outcomes, and agrees to the service after the barber explains the process, products, and any contraindications", "Signs a legal waiver releasing the barber from all liability", "Pays a deposit before the consultation begins", "Provides a doctor's note confirming their hair is healthy enough for chemical services"], options_es: ["Entienda los riesgos y resultados potenciales, y acepte el servicio después de que el barbero explique el proceso, los productos y cualquier contraindicación", "Firme una exención legal liberando al barbero de toda responsabilidad", "Pague un depósito antes de que comience la consulta", "Proporcione una nota médica confirmando que su cabello está lo suficientemente saludable para los servicios químicos"], correct: 0, explanation: "Informed consent means explaining the service, products, risks, and expected outcomes to the client and getting their agreement before proceeding. While not always legally required as a signed document in barbershops, it is an ethical and professional standard." },
  { id: 333, question: "Which statement about hydroxide relaxers and thio (ammonium thioglycolate) relaxers is TRUE?", question_es: "¿Cuál enunciado sobre los relajadores de hidróxido y los relajadores thio (tioglicolato de amonio) es VERDADERO?", options: ["Hydroxide relaxers permanently convert disulfide bonds to lanthionine bonds (cannot be reversed); thio relaxers reduce disulfide bonds temporarily (can be reformed)", "Both hydroxide and thio relaxers permanently convert bonds using the same chemistry", "Thio relaxers are more alkaline and stronger than hydroxide relaxers", "Hydroxide relaxers can be followed immediately by a thio perm for additional curl"], options_es: ["Los relajadores de hidróxido convierten permanentemente los enlaces disulfuro en enlaces de lantionina (no pueden revertirse); los relajadores thio reducen los enlaces disulfuro temporalmente (pueden reformarse)", "Tanto los relajadores de hidróxido como los thio convierten permanentemente los enlaces usando la misma química", "Los relajadores thio son más alcalinos y más fuertes que los relajadores de hidróxido", "Los relajadores de hidróxido pueden ir seguidos inmediatamente de una permanente thio para rizo adicional"], correct: 0, explanation: "Hydroxide relaxers permanently change S–S bonds to lanthionine (C–S–C) bonds through lanthionization — an irreversible change. Thio relaxers break S–S bonds through reduction — a reversible process that can be re-oxidized. These are chemically incompatible systems." },
  { id: 334, question: "When selecting a perm formula for a client, which hair type requires the mildest (lowest pH) formula?", question_es: "Al seleccionar una fórmula de permanente para un cliente, ¿qué tipo de cabello requiere la fórmula más suave (pH más bajo)?", options: ["Fine, color-treated, or damaged hair with high porosity", "Coarse, resistant hair with low porosity", "Natural, never-processed hair in excellent condition", "Tightly coiled hair with high density"], options_es: ["Cabello fino, tratado con color o dañado con alta porosidad", "Cabello grueso y resistente con baja porosidad", "Cabello natural, nunca procesado en excelente condición", "Cabello muy rizado con alta densidad"], correct: 0, explanation: "Fine, color-treated, or damaged hair is already fragile and highly porous. A mild, low-pH formula (acid-balanced perm) minimizes additional stress. Coarse, resistant, low-porosity hair needs a stronger, higher-pH formula to penetrate and process effectively." },
  { id: 335, question: "After a relaxer service, a deep conditioning or protein treatment is recommended because:", question_es: "Después de un servicio de relajador, se recomienda un tratamiento de acondicionamiento profundo o proteína porque:", options: ["Relaxers break disulfide bonds and strip moisture, leaving the hair porous, weakened, and in need of protein and moisture replenishment", "It removes any remaining relaxer from the hair shaft", "It helps straighten the hair further to enhance the relaxer results", "Conditioning prepares the hair for a color service the same day"], options_es: ["Los relajadores rompen los enlaces disulfuro y eliminan la humedad, dejando el cabello poroso, debilitado y necesitado de reposición de proteínas y humedad", "Elimina cualquier relajador restante del eje del cabello", "Ayuda a alisar el cabello aún más para mejorar los resultados del relajador", "El acondicionamiento prepara el cabello para un servicio de color el mismo día"], correct: 0, explanation: "Chemical relaxers damage the hair's protein structure (cortex) and strip natural moisture. Post-relaxer protein and moisture treatments help rebuild the weakened protein structure, reduce porosity, and restore moisture balance to keep relaxed hair healthy." },
  { id: 336, question: "Texas TDLR requires that a licensed barber performing chemical waving or relaxing services:", question_es: "TDLR de Texas requiere que un barbero con licencia que realiza servicios de ondulación química o alisado:", options: ["Follow the manufacturer's instructions for all chemical products used and comply with all state sanitation and safety standards", "Obtain a separate chemical service license in addition to the barbering license", "Record every chemical service in a state-maintained database", "Use only TDLR-approved brands of perm and relaxer products"], options_es: ["Siga las instrucciones del fabricante para todos los productos químicos usados y cumpla con todos los estándares estatales de saneamiento y seguridad", "Obtenga una licencia de servicio químico separada además de la licencia de barbería", "Registre cada servicio químico en una base de datos mantenida por el estado", "Use solo marcas aprobadas por TDLR de productos de permanente y relajador"], correct: 0, explanation: "Texas barbering license covers chemical services including perms and relaxers. TDLR requires barbers to follow manufacturer product instructions, comply with state sanitation rules, and maintain client records. No separate license is needed for chemical services." },
]

// First 45 Haircoloring questions (ids 337–381)
const hcT = `"Haircoloring"`, hcTes = `"Coloración del Cabello"`
const hcQ = [
  { id: 337, question: "The natural pigment responsible for hair color is called:", question_es: "El pigmento natural responsable del color del cabello se llama:", options: ["Melanin, produced by melanocytes in the hair follicle", "Keratin, the primary structural protein of hair", "Cortisol, a stress hormone affecting pigment production", "Tannin, a plant-based pigment"], options_es: ["Melanina, producida por los melanocitos en el folículo piloso", "Queratina, la proteína estructural principal del cabello", "Cortisol, una hormona del estrés que afecta la producción de pigmento", "Tanino, un pigmento de origen vegetal"], correct: 0, explanation: "Melanin is the natural pigment found in the cortex of the hair shaft. It is produced by melanocytes at the base of the hair follicle and determines natural hair color. As melanocytes slow production with age, hair becomes gray or white." },
  { id: 338, question: "The two types of melanin that determine hair color are:", question_es: "Los dos tipos de melanina que determinan el color del cabello son:", options: ["Eumelanin (brown/black pigment) and pheomelanin (red/yellow pigment)", "Eumelanin (yellow pigment) and pheomelanin (black pigment)", "Tyrosinase (dark) and albinase (light)", "Melanocyte A (cool) and Melanocyte B (warm)"], options_es: ["Eumelanina (pigmento marrón/negro) y feomelanina (pigmento rojo/amarillo)", "Eumelanina (pigmento amarillo) y feomelanina (pigmento negro)", "Tirosinasa (oscura) y albinasa (clara)", "Melanocito A (frío) y Melanocito B (cálido)"], correct: 0, explanation: "Eumelanin produces brown to black colors; pheomelanin produces red, orange, and yellow colors. The ratio of these two pigments in the cortex determines an individual's natural hair color." },
  { id: 339, question: "The hair color level system numbers hair from:", question_es: "El sistema de niveles de color de cabello numera el cabello del:", options: ["Level 1 (black — darkest) to Level 10 (lightest blonde) — or up to 12 in some systems", "Level 1 (white) to Level 10 (jet black)", "Level 1 (fine) to Level 10 (coarse) based on texture", "Level 1 (red) to Level 10 (blue) based on tone"], options_es: ["Nivel 1 (negro — más oscuro) al Nivel 10 (rubio más claro) — o hasta 12 en algunos sistemas", "Nivel 1 (blanco) al Nivel 10 (negro azabache)", "Nivel 1 (fino) al Nivel 10 (grueso) según la textura", "Nivel 1 (rojo) al Nivel 10 (azul) según el tono"], correct: 0, explanation: "The level system is a scale that measures the relative lightness or darkness of hair. Level 1 = black (darkest); Level 10 = lightest blonde (in a 1-10 system) or Level 12 in extended systems. Levels increase as hair gets lighter." },
  { id: 340, question: "The three primary colors in the standard color wheel used in hair coloring are:", question_es: "Los tres colores primarios en la rueda de colores estándar usada en la coloración del cabello son:", options: ["Red, yellow, and blue", "Red, green, and blue (RGB)", "Cyan, magenta, and yellow", "Orange, violet, and green"], options_es: ["Rojo, amarillo y azul", "Rojo, verde y azul (RGB)", "Cian, magenta y amarillo", "Naranja, violeta y verde"], correct: 0, explanation: "In hair color theory (using the subtractive color model), the three primary colors are red, yellow, and blue. These cannot be created by mixing other colors and are the basis for all other colors on the wheel." },
  { id: 341, question: "The secondary colors formed by mixing equal parts of two primary colors are:", question_es: "Los colores secundarios formados al mezclar partes iguales de dos colores primarios son:", options: ["Orange (red + yellow), green (yellow + blue), and violet (red + blue)", "Brown (red + blue), gray (yellow + blue), and tan (red + yellow)", "Teal (yellow + blue), mauve (red + blue), and gold (red + yellow)", "Purple (red + yellow), teal (yellow + blue), and maroon (red + blue)"], options_es: ["Naranja (rojo + amarillo), verde (amarillo + azul) y violeta (rojo + azul)", "Marrón (rojo + azul), gris (amarillo + azul) y tostado (rojo + amarillo)", "Verde azulado (amarillo + azul), malva (rojo + azul) y dorado (rojo + amarillo)", "Morado (rojo + amarillo), verde azulado (amarillo + azul) y granate (rojo + azul)"], correct: 0, explanation: "Secondary colors: Red + Yellow = Orange; Yellow + Blue = Green; Red + Blue = Violet (Purple). Secondary colors sit between the primary colors they are made from on the color wheel." },
  { id: 342, question: "Complementary colors on the color wheel are:", question_es: "Los colores complementarios en la rueda de colores son:", options: ["Colors directly opposite each other on the wheel — they neutralize each other when mixed (e.g., red and green, blue and orange, yellow and violet)", "Colors that are adjacent to each other and blend harmoniously", "Colors within the same warm or cool family", "Colors that are two steps apart on the wheel"], options_es: ["Colores directamente opuestos entre sí en la rueda — se neutralizan mutuamente cuando se mezclan (p. ej., rojo y verde, azul y naranja, amarillo y violeta)", "Colores que son adyacentes entre sí y se mezclan armoniosamente", "Colores dentro de la misma familia cálida o fría", "Colores que están separados dos pasos en la rueda"], correct: 0, explanation: "Complementary colors sit opposite each other on the color wheel. When mixed, they neutralize each other (producing brown or gray). This principle is used in hair coloring to cancel unwanted tones — e.g., a violet toner cancels yellow brassiness." },
  { id: 343, question: "To neutralize unwanted brassy (orange/yellow) tones after bleaching, a colorist would use:", question_es: "Para neutralizar los tonos no deseados de bronce (naranja/amarillo) después del aclarado, un colorista usaría:", options: ["A violet (purple) or blue toner, since violet and blue are complementary to yellow and orange", "An orange gloss to enhance the warm tones further", "A red-based toner to intensify the warmth", "A neutral brown to add depth"], options_es: ["Un tónico violeta (morado) o azul, ya que el violeta y el azul son complementarios al amarillo y el naranja", "Un gloss naranja para realzar aún más los tonos cálidos", "Un tónico de base roja para intensificar el calor", "Un marrón neutro para añadir profundidad"], correct: 0, explanation: "Violet neutralizes yellow (complementary pair), and blue neutralizes orange (complementary pair). Purple/violet toners are used on very light blonde to neutralize yellow; blue-toned products are used on darker blonde/light brown to cancel orange brassiness." },
  { id: 344, question: "A temporary hair color:", question_es: "Un color de cabello temporal:", options: ["Coats only the surface of the cuticle; is removed with one or two shampoos; and does not require a developer", "Penetrates into the cortex and lasts 4–6 weeks", "Permanently changes the hair's natural pigment through oxidation", "Requires a 20-volume developer to deposit color"], options_es: ["Cubre solo la superficie de la cutícula; se elimina con uno o dos champús; y no requiere un revelador", "Penetra en el córtex y dura 4–6 semanas", "Cambia permanentemente el pigmento natural del cabello a través de la oxidación", "Requiere un revelador de 20 volúmenes para depositar color"], correct: 0, explanation: "Temporary color (rinses, color sprays, color-depositing shampoos) coats only the outer cuticle. It washes out with one or two shampoos, contains no developer/peroxide, and cannot lighten hair — only add or enhance color." },
  { id: 345, question: "A semi-permanent hair color:", question_es: "Un color de cabello semi-permanente:", options: ["Penetrates slightly into the cuticle/cortex, lasts 4–6 weeks without a developer, fades gradually, and cannot lighten hair", "Requires 20-volume developer to open the cuticle and deposit color", "Permanently changes hair color through oxidation and is not removed by shampooing", "Lasts only until the next shampoo and coats only the cuticle surface"], options_es: ["Penetra ligeramente en la cutícula/córtex, dura 4–6 semanas sin revelador, se desvanece gradualmente y no puede aclarar el cabello", "Requiere revelador de 20 volúmenes para abrir la cutícula y depositar color", "Cambia permanentemente el color del cabello a través de la oxidación y no se elimina con el champú", "Dura solo hasta el próximo champú y cubre solo la superficie de la cutícula"], correct: 0, explanation: "Semi-permanent color penetrates slightly into the cuticle/outer cortex. It requires no developer, lasts 4-6 shampoos (some formulas up to 6 weeks), fades gradually, and cannot lighten hair — only deposit color on same-level or darker hair." },
  { id: 346, question: "A demi-permanent (deposit-only) hair color:", question_es: "Un color de cabello demi-permanente (solo deposición):", options: ["Requires a low-volume developer (5–10 vol), deposits color without lightening, lasts longer than semi-permanent but fades over time — no harsh line of demarcation", "Requires 30-volume developer for maximum lift", "Contains bleach powder for lightening effect", "Permanently bonds to the cortex with no fading over time"], options_es: ["Requiere un revelador de bajo volumen (5–10 vol), deposita color sin aclarar, dura más que el semi-permanente pero se desvanece con el tiempo — sin línea de demarcación severa", "Requiere revelador de 30 volúmenes para máximo levantamiento", "Contiene polvo decolorante para efecto aclarante", "Se une permanentemente al córtex sin desvanecimiento con el tiempo"], correct: 0, explanation: "Demi-permanent color uses a low-volume (5-10 vol) developer. It penetrates the cortex more than semi-permanent, lasts longer (fades over 20-28 shampoos), deposits color without lightening, and leaves no harsh regrowth line — ideal for blending gray or refreshing color." },
  { id: 347, question: "A permanent oxidative hair color:", question_es: "Un color de cabello oxidativo permanente:", options: ["Uses hydrogen peroxide developer to open the cuticle, disperse natural pigment, and permanently deposit artificial pigment — it can lift and deposit", "Fades with shampooing over 6–8 weeks", "Contains no ammonia and requires no developer", "Only deposits color without affecting the natural melanin"], options_es: ["Usa revelador de peróxido de hidrógeno para abrir la cutícula, dispersar el pigmento natural y depositar permanentemente pigmento artificial — puede aclarar y depositar", "Se desvanece con el champú en 6–8 semanas", "No contiene amoníaco y no requiere revelador", "Solo deposita color sin afectar la melanina natural"], correct: 0, explanation: "Permanent oxidative color requires developer (hydrogen peroxide). The developer swells the cuticle, allows color molecules to penetrate, disperses some natural melanin, and oxidizes the new color molecules to their final color permanently in the cortex." },
  { id: 348, question: "10-volume developer is used when:", question_es: "El revelador de 10 volúmenes se usa cuando:", options: ["Depositing color with little to no lift (e.g., going darker, toning, or slight color refresh)", "Lifting hair 2 levels above its natural color", "Bleaching hair to platinum in one session", "Performing maximum lift with high-lift color"], options_es: ["Depositando color con poco o ningún levantamiento (p. ej., oscurecer, tonificar o refrescar ligeramente el color)", "Levantando el cabello 2 niveles por encima de su color natural", "Decolorando el cabello a platino en una sesión", "Realizando levantamiento máximo con color de alto levantamiento"], correct: 0, explanation: "10-volume (3% hydrogen peroxide) developer provides minimal lift. It is used to deposit color without significant lightening — for toning, going darker, refreshing existing color, or blending a small percentage of gray." },
  { id: 349, question: "20-volume developer is most commonly used for:", question_es: "El revelador de 20 volúmenes se usa más comúnmente para:", options: ["Standard permanent color applications — it provides 1–2 levels of lift while depositing color", "Maximum lift (4–5 levels) on resistant hair", "Deposit-only (no lift) applications", "Bleach applications requiring rapid lightening"], options_es: ["Aplicaciones estándar de color permanente — proporciona 1–2 niveles de levantamiento mientras deposita color", "Levantamiento máximo (4–5 niveles) en cabello resistente", "Aplicaciones de solo deposición (sin levantamiento)", "Aplicaciones de decolorante que requieren aclarado rápido"], correct: 0, explanation: "20-volume (6% hydrogen peroxide) is the most common developer for standard permanent color. It provides 1-2 levels of lift and works well for full coverage, going lighter by 1-2 levels, and standard color services including gray coverage." },
  { id: 350, question: "30-volume developer provides:", question_es: "El revelador de 30 volúmenes proporciona:", options: ["2–3 levels of lift, used for lightening darker hair more significantly or for stubborn gray coverage", "1 level of lift maximum — the standard for most services", "4–5 levels of lift — used for high-lift color", "No lift — only deposit color"], options_es: ["2–3 niveles de levantamiento, usado para aclarar cabello más oscuro de manera más significativa o para cobertura de canas resistentes", "Máximo 1 nivel de levantamiento — el estándar para la mayoría de los servicios", "4–5 niveles de levantamiento — usado para color de alto levantamiento", "Sin levantamiento — solo deposita color"], correct: 0, explanation: "30-volume (9% hydrogen peroxide) developer provides 2-3 levels of lift. It is used for more significant lightening, covering stubborn or coarse gray hair, and situations where 20-volume does not provide enough lift." },
  { id: 351, question: "40-volume developer should be used:", question_es: "El revelador de 40 volúmenes debe usarse:", options: ["Only for high-lift blonde colors or very resistant hair that requires maximum lift (3–4 levels) — with caution due to higher scalp sensitivity risk", "As the standard developer for all permanent color applications", "For deposit-only applications such as darkening or toning", "Whenever gray coverage is needed"], options_es: ["Solo para colores rubios de alto levantamiento o cabello muy resistente que requiere levantamiento máximo (3–4 niveles) — con precaución debido al mayor riesgo de sensibilidad del cuero cabelludo", "Como el revelador estándar para todas las aplicaciones de color permanente", "Para aplicaciones de solo deposición como oscurecer o tonificar", "Siempre que se necesite cobertura de canas"], correct: 0, explanation: "40-volume (12% hydrogen peroxide) developer provides 3-4 levels of lift. It is used for high-lift blonde applications and very resistant hair. It has the highest risk of scalp irritation and must be used cautiously." },
  { id: 352, question: "Before applying a permanent hair color to a client for the first time, the barber should perform:", question_es: "Antes de aplicar un color de cabello permanente a un cliente por primera vez, el barbero debe realizar:", options: ["A patch test (allergy test / skin sensitivity test) 24–48 hours before the color service", "A strand test immediately before application only", "A porosity test as the sole pre-service assessment", "No test is required — permanent color is safe for all clients"], options_es: ["Una prueba de parche (prueba de alergia / prueba de sensibilidad cutánea) 24–48 horas antes del servicio de color", "Solo una prueba de mechón inmediatamente antes de la aplicación", "Una prueba de porosidad como la única evaluación previa al servicio", "No se requiere prueba — el color permanente es seguro para todos los clientes"], correct: 0, explanation: "A patch (sensitivity) test detects potential allergic reactions to PPD (para-phenylenediamine) or other color ingredients. It must be performed 24-48 hours before the service by applying a small amount of color to the inner elbow or behind the ear." },
  { id: 353, question: "The purpose of a strand test before a hair color service is to:", question_es: "El propósito de una prueba de mechón antes de un servicio de color de cabello es:", options: ["Preview the color result and timing on a small section of hair before applying to the entire head", "Check for allergic reactions on the skin", "Determine how many tubes of color are needed", "Test if the developer is the correct volume"], options_es: ["Ver el resultado del color y el tiempo en una pequeña sección de cabello antes de aplicar en toda la cabeza", "Verificar reacciones alérgicas en la piel", "Determinar cuántos tubos de color se necesitan", "Verificar si el revelador es el volumen correcto"], correct: 0, explanation: "A strand test is performed on a small section of hair (usually from a hidden area) to assess the color result, verify processing time, and determine how the hair responds to the specific formula before committing to the full application." },
  { id: 354, question: "Hair color is classified as 'oxidative' when it:", question_es: "El color de cabello se clasifica como 'oxidativo' cuando:", options: ["Requires hydrogen peroxide (developer) to develop the color through a chemical oxidation process", "Contains no peroxide and is applied directly to dry hair", "Fades within 6–8 shampoos without any permanent change", "Is applied with heat only and contains no chemicals"], options_es: ["Requiere peróxido de hidrógeno (revelador) para desarrollar el color a través de un proceso de oxidación química", "No contiene peróxido y se aplica directamente en cabello seco", "Se desvanece en 6–8 champús sin ningún cambio permanente", "Se aplica solo con calor y no contiene químicos"], correct: 0, explanation: "Oxidative color requires hydrogen peroxide as a developer. The oxidation reaction develops the color molecules (dye intermediates) inside the hair shaft from small, colorless molecules into large, colored molecules that are too large to wash out." },
  { id: 355, question: "Para-phenylenediamine (PPD) is:", question_es: "La para-fenilenediamina (PPD) es:", options: ["A primary oxidative dye intermediate found in most permanent hair colors, which can cause allergic contact dermatitis in sensitized individuals", "A developer used to accelerate color processing", "A conditioning ingredient added to hair dye formulas", "A natural plant-based dye (henna) ingredient"], options_es: ["Un intermediario de tinte oxidativo primario encontrado en la mayoría de los colores de cabello permanentes, que puede causar dermatitis de contacto alérgica en personas sensibilizadas", "Un revelador usado para acelerar el procesamiento del color", "Un ingrediente acondicionador añadido a las fórmulas de tinte", "Un ingrediente de tinte de origen vegetal (henna)"], correct: 0, explanation: "PPD (para-phenylenediamine) is the primary colorant in most permanent oxidative hair dyes. It can cause allergic reactions in sensitized individuals — ranging from mild irritation to severe anaphylaxis. The patch test is performed specifically to detect PPD sensitivity." },
  { id: 356, question: "When applying a single-process permanent color to virgin (previously uncolored) hair, the application begins:", question_es: "Al aplicar un color permanente de proceso único en cabello virgen (sin color previo), la aplicación comienza:", options: ["At the midshaft (1/2 inch from the scalp), then the mid-lengths, and finally the roots last — because the scalp's heat processes faster near the roots", "At the roots first, then the midshaft, and finally the ends", "At the ends first to process the most resistant area", "Evenly from root to end all at once"], options_es: ["En el punto medio (1/2 pulgada desde el cuero cabelludo), luego los medios, y finalmente las raíces al final — porque el calor del cuero cabelludo procesa más rápido cerca de las raíces", "Primero en las raíces, luego en el punto medio y finalmente en las puntas", "Primero en las puntas para procesar el área más resistente", "Uniformemente de raíz a punta todo a la vez"], correct: 0, explanation: "For virgin hair applications, color is applied starting 1/2 inch from the scalp (midshaft), then the ends, and the root area is done last. Body heat near the scalp accelerates processing — applying roots last ensures even color development throughout." },
  { id: 357, question: "A color retouch application (touch-up) applies color only to:", question_es: "Una aplicación de retoque de color aplica color solo en:", options: ["The new growth (virgin regrowth) since the previous service, to avoid re-coloring already-processed hair", "The entire hair shaft from root to end", "The ends only to refresh faded color", "The most visibly faded area regardless of where it is"], options_es: ["El nuevo crecimiento (nuevo crecimiento virgen) desde el servicio anterior, para evitar re-colorear cabello ya procesado", "Todo el eje del cabello de raíz a punta", "Solo las puntas para refrescar el color desvanecido", "El área más visiblemente desvanecida independientemente de dónde esté"], correct: 0, explanation: "A color retouch applies color only to the new growth between the scalp and the previously colored hair. Applying over already-colored hair causes double processing — resulting in a hard line, uneven depth, and potential damage." },
  { id: 358, question: "The 'contributing pigment' (undertone) is the underlying warm pigment revealed when hair is lightened. What is the underlying pigment at Level 6 (dark blonde/light brown)?", question_es: "El 'pigmento contribuyente' (subtono) es el pigmento cálido subyacente que se revela cuando el cabello se aclara. ¿Cuál es el pigmento subyacente en el Nivel 6 (rubio oscuro/marrón claro)?", options: ["Orange-red", "Pale yellow", "Deep red-orange (almost red-brown)", "Yellow-gold"], options_es: ["Naranja-rojo", "Amarillo pálido", "Naranja-rojo profundo (casi marrón rojizo)", "Amarillo-dorado"], correct: 0, explanation: "As hair is lightened through its natural melanin stages, Level 6 reveals an orange-red contributing pigment. Darker levels (1-4) reveal red to red-orange; mid-levels (5-7) orange to gold; lighter levels (8-10) yellow to pale yellow." },
  { id: 359, question: "Which underlying pigment is revealed when hair is lightened to Level 9–10 (very light blonde)?", question_es: "¿Qué pigmento subyacente se revela cuando el cabello se aclara al Nivel 9–10 (rubio muy claro)?", options: ["Pale yellow to nearly white-yellow", "Deep orange", "Red-orange", "Neutral brown"], options_es: ["Amarillo pálido a casi amarillo-blanco", "Naranja profundo", "Naranja-rojo", "Marrón neutro"], correct: 0, explanation: "At Levels 9-10, most melanin has been dispersed, leaving pale yellow to nearly white-yellow contributing pigment. This is why violet/purple toners are used at this level — to neutralize the remaining yellow cast for bright, cool blonde results." },
  { id: 360, question: "A 'double-process' haircoloring involves:", question_es: "La coloración del cabello de 'doble proceso' implica:", options: ["First decolorizing (bleaching) the hair to remove natural and artificial pigment, then toning with a second formula to achieve the desired final color", "Applying two coats of the same color formula for deeper saturation", "Using two different permanent colors applied to different sections", "Performing color and perm services in the same appointment"], options_es: ["Primero decolorar (blanquear) el cabello para eliminar el pigmento natural y artificial, luego tonificar con una segunda fórmula para lograr el color final deseado", "Aplicar dos capas de la misma fórmula de color para una saturación más profunda", "Usar dos colores permanentes diferentes aplicados en diferentes secciones", "Realizar servicios de color y permanente en la misma cita"], correct: 0, explanation: "Double-process color: Step 1 = bleach/decolorize the hair to remove natural melanin (lightening); Step 2 = apply toner or color to deposit the desired final shade. This is used to achieve very light, cool, or vivid colors not achievable with single-process color." },
  { id: 361, question: "Hair lightener (bleach) works by:", question_es: "El aclarante de cabello (blanqueador) trabaja mediante:", options: ["Decolorizing (dispersing/dissolving) the melanin granules in the cortex through an oxidation process, progressively lightening the hair", "Adding a coating of white pigment over the natural color", "Cutting the hair's protein structure to remove color molecules", "Depositing a light-reflecting agent inside the cortex"], options_es: ["Decolorando (dispersando/disolviendo) los gránulos de melanina en el córtex a través de un proceso de oxidación, aclarando progresivamente el cabello", "Añadiendo una capa de pigmento blanco sobre el color natural", "Cortando la estructura proteica del cabello para eliminar las moléculas de color", "Depositando un agente que refleja la luz dentro del córtex"], correct: 0, explanation: "Bleach (lightener) contains oxidizing agents (hydrogen peroxide) that oxidize and disperse the melanin pigment granules within the cortex. As melanin is dispersed, the hair progresses through the stages of lightening from black to red to orange to yellow to pale yellow." },
  { id: 362, question: "A 'toner' is applied after bleaching primarily to:", question_es: "Un 'tónico' se aplica después del aclarado principalmente para:", options: ["Neutralize unwanted warm (brassy) tones and deposit the desired cool, neutral, or fashion tone onto pre-lightened hair", "Add protein to rebuild bleach-damaged hair", "Darken the hair back toward its natural level after lightening", "Condition and seal the cuticle after the bleaching process"], options_es: ["Neutralizar los tonos cálidos no deseados (bronce) y depositar el tono frío, neutro o de moda deseado en el cabello pre-aclarado", "Añadir proteína para reconstruir el cabello dañado por el aclarado", "Oscurecer el cabello de vuelta hacia su nivel natural después del aclarado", "Acondicionar y sellar la cutícula después del proceso de aclarado"], correct: 0, explanation: "Toners are semi-permanent or demi-permanent colors applied to pre-lightened (bleached) hair to neutralize brassiness, add shine, and achieve the final desired tone — such as platinum, ash blonde, rose gold, or silver." },
  { id: 363, question: "Gray hair presents a special challenge for color coverage because:", question_es: "El cabello gris presenta un desafío especial para la cobertura de color porque:", options: ["Gray hair contains little to no melanin, has a tightly closed cuticle, and can be resistant to color penetration — often requiring longer processing or higher developer", "Gray hair is always fine and therefore absorbs color more quickly", "Gray hair has the same porosity as pigmented hair and requires no formula adjustment", "Gray hair darkens to black naturally if color is applied for long enough"], options_es: ["El cabello gris contiene poca o ninguna melanina, tiene una cutícula bien cerrada y puede ser resistente a la penetración del color — a menudo requiere más tiempo de procesamiento o un revelador de mayor volumen", "El cabello gris siempre es fino y por lo tanto absorbe el color más rápidamente", "El cabello gris tiene la misma porosidad que el cabello pigmentado y no requiere ajuste de fórmula", "El cabello gris se oscurece a negro naturalmente si se aplica color el tiempo suficiente"], correct: 0, explanation: "Gray/white hair has no melanin and often has a tightly packed, resistant cuticle. This resistance means color molecules have difficulty penetrating. A higher-volume developer (20-30 vol) and adequate processing time ensure thorough coverage." },
  { id: 364, question: "When formulating color to achieve 100% gray coverage on resistant gray hair, the colorist should:", question_es: "Al formular color para lograr cobertura de canas al 100% en cabello gris resistente, el colorista debe:", options: ["Use a formula that includes a warm tone or neutral base to help the color grab onto resistant gray, along with adequate developer volume", "Use the coolest, most ash-based formula available for the most natural result", "Use a deposit-only (no developer) color for gentle coverage", "Apply the color for only 5 minutes to avoid over-processing"], options_es: ["Usar una fórmula que incluya un tono cálido o base neutral para ayudar al color a agarrarse al gris resistente, junto con el volumen de revelador adecuado", "Usar la fórmula más fría y con base ceniza disponible para el resultado más natural", "Usar un color de solo deposición (sin revelador) para cobertura suave", "Aplicar el color por solo 5 minutos para evitar el sobreprocesamiento"], correct: 0, explanation: "Resistant gray hair often benefits from a formula that includes warm or natural tones rather than very cool ash tones, because ash tones can reflect off resistant gray strands. Natural/warm bases help 'grab' the color on smooth, resistant cuticles." },
  { id: 365, question: "The color result when equal parts of all three primary colors are mixed is:", question_es: "El resultado de color cuando se mezclan partes iguales de los tres colores primarios es:", options: ["Brown or gray (a neutral, muted tone)", "A bright, vivid green", "Pure white", "Black"], options_es: ["Marrón o gris (un tono neutro y apagado)", "Un verde brillante y vívido", "Blanco puro", "Negro"], correct: 0, explanation: "Mixing all three primary colors (red + yellow + blue) in equal parts creates a neutral brown or gray-brown. This principle is used in color theory when you need to 'muddy' or neutralize an overly vivid color result." },
  { id: 366, question: "Which hair color classification fades most gradually and has the longest-lasting results?", question_es: "¿Qué clasificación de color de cabello se desvanece más gradualmente y tiene los resultados más duraderos?", options: ["Permanent oxidative color (requires developer, does not wash out — only grows out)", "Demi-permanent color (fades over 20–28 shampoos)", "Semi-permanent color (fades over 4–6 shampoos)", "Temporary color (fades after 1–2 shampoos)"], options_es: ["Color oxidativo permanente (requiere revelador, no se lava — solo crece)", "Color demi-permanente (se desvanece en 20–28 champús)", "Color semi-permanente (se desvanece en 4–6 champús)", "Color temporal (se desvanece después de 1–2 champús)"], correct: 0, explanation: "Permanent oxidative color does not wash out — the large color molecules are permanently lodged within the cortex. The color only disappears as new hair grows in at the roots, requiring a retouch every 4-6 weeks on fast growers." },
  { id: 367, question: "Henna is classified as what type of hair color?", question_es: "La henna se clasifica como qué tipo de color de cabello?", options: ["A natural/plant-based color that coats the hair shaft; it is NOT compatible with chemical perm or relaxer services due to metallic salt content in compound henna", "A demi-permanent oxidative color requiring developer", "A semi-permanent penetrating color that lasts 4–6 weeks", "A temporary surface coating removed with one shampoo"], options_es: ["Un color natural/de origen vegetal que cubre el eje del cabello; NO es compatible con los servicios de permanente o relajador químico debido al contenido de sales metálicas en la henna compuesta", "Un color demi-permanente oxidativo que requiere revelador", "Un color semi-permanente de penetración que dura 4–6 semanas", "Un recubrimiento superficial temporal eliminado con un champú"], correct: 0, explanation: "Natural henna (pure henna from the Lawsonia inermis plant) coats the hair shaft. 'Compound henna' contains metallic salts, making it incompatible with chemical services. A strand test with a metallic salt test solution is essential before any chemical service on henna-treated hair." },
  { id: 368, question: "A 'high-lift' color is designed to:", question_es: "Un color de 'alto levantamiento' está diseñado para:", options: ["Lift hair 3–5 levels lighter in a single process using 40-volume developer, on light natural hair (Levels 6 or lighter)", "Deposit color without any lightening effect", "Lift hair only 1 level and is used with 10-volume developer", "Work on all natural hair levels from 1 to 10"], options_es: ["Aclarar el cabello 3–5 niveles en un solo proceso usando revelador de 40 volúmenes, en cabello natural claro (Nivel 6 o más claro)", "Depositar color sin ningún efecto aclarante", "Aclarar el cabello solo 1 nivel y se usa con revelador de 10 volúmenes", "Funcionar en todos los niveles de cabello natural del 1 al 10"], correct: 0, explanation: "High-lift color contains extra ammonia and is mixed with 40-volume developer for maximum lift (3-5 levels). It is only effective on Level 6 and lighter natural hair — attempting to use it on dark hair will not achieve the expected result and may cause damage." },
  { id: 369, question: "The term 'warm' tones in hair color refers to:", question_es: "El término tonos 'cálidos' en el color de cabello se refiere a:", options: ["Colors based on red, orange, and yellow — which appear on the warm side of the color wheel", "Colors based on blue, green, and violet — which create a cool appearance", "Colors with a neutral pH that neither lift nor deposit warmth", "Colors that process best at higher temperatures"], options_es: ["Colores basados en rojo, naranja y amarillo — que aparecen en el lado cálido de la rueda de colores", "Colores basados en azul, verde y violeta — que crean una apariencia fría", "Colores con un pH neutro que ni levanta ni deposita calidez", "Colores que procesan mejor a temperaturas más altas"], correct: 0, explanation: "Warm tones are red, orange, golden, and yellow-based — they appear on the warm half of the color wheel and add richness, vibrancy, and warmth to hair. Cool tones (ash, blue, violet, green) are on the opposite side and create cooler, neutral appearances." },
  { id: 370, question: "'Ash' tones in hair color are based on which color?", question_es: "Los tonos 'ceniza' en el color de cabello están basados en qué color?", options: ["Blue and violet (cool tones) — ash colors neutralize warm tones and create cool, muted results", "Red and orange (warm tones) — ash adds warmth to dark hair", "Green and yellow (natural tones) — ash colors blend naturally with brown hair", "Gold and copper — ash colors enhance warm undertones"], options_es: ["Azul y violeta (tonos fríos) — los colores ceniza neutralizan los tonos cálidos y crean resultados fríos y apagados", "Rojo y naranja (tonos cálidos) — la ceniza añade calidez al cabello oscuro", "Verde y amarillo (tonos naturales) — los colores ceniza se mezclan naturalmente con el cabello marrón", "Dorado y cobre — los colores ceniza realzan los subtonos cálidos"], correct: 0, explanation: "Ash tones are blue/violet-based cool tones. They suppress warmth in the hair and create cool, muted, smoky results. Ash colors are used on naturally warm or brassy hair to neutralize unwanted warm tones." },
  { id: 371, question: "When a client's hair processes unevenly during color application (some sections darker, some lighter), the most likely cause is:", question_es: "Cuando el cabello de un cliente se procesa de manera desigual durante la aplicación de color (algunas secciones más oscuras, otras más claras), la causa más probable es:", options: ["Uneven porosity throughout the hair, with high-porosity sections absorbing more color faster than low-porosity sections", "Using too much or too little color product overall", "Incorrect mixing ratio of color to developer", "The color sitting too long before processing"], options_es: ["Porosidad desigual en todo el cabello, con secciones de alta porosidad absorbiendo más color más rápido que las secciones de baja porosidad", "Usar demasiado o muy poco producto de color en general", "Relación de mezcla incorrecta de color a revelador", "El color esperando demasiado antes de procesar"], correct: 0, explanation: "Uneven porosity (high porosity at ends from heat/chemical damage, lower at roots) causes uneven color absorption. High-porosity sections absorb color faster → appear darker or more saturated; low-porosity sections resist penetration → may be lighter." },
  { id: 372, question: "The proper mixing ratio for most permanent hair colors to developer is:", question_es: "La relación de mezcla adecuada para la mayoría de los colores de cabello permanentes con el revelador es:", options: ["1:1 or 1:2 (1 part color to 1 or 2 parts developer) — always follow the manufacturer's specific instructions", "2:1 (2 parts color to 1 part developer) for maximum pigment", "3:1 (3 parts developer to 1 part color) for all services", "Equal parts color, developer, and water (1:1:1)"], options_es: ["1:1 o 1:2 (1 parte de color por 1 o 2 partes de revelador) — siempre siga las instrucciones específicas del fabricante", "2:1 (2 partes de color por 1 parte de revelador) para máximo pigmento", "3:1 (3 partes de revelador por 1 parte de color) para todos los servicios", "Partes iguales de color, revelador y agua (1:1:1)"], correct: 0, explanation: "Most permanent colors are mixed 1:1 (1 oz color : 1 oz developer) or 1:1.5 or 1:2 depending on the brand and application method. Always follow manufacturer instructions — incorrect mixing ratios affect color development, lift, and final results." },
  { id: 373, question: "Color 'filler' is used in hair coloring to:", question_es: "El 'relleno' de color se usa en la coloración del cabello para:", options: ["Re-deposit missing underlying pigment (warm tones) into hair that has been lightened before re-darkening — preventing flat, dull, or green results", "Fill in thinning areas on the scalp to simulate hair density", "Add protein to extremely damaged hair before chemical color", "Temporarily coat the cuticle for shine enhancement"], options_es: ["Re-depositar el pigmento subyacente faltante (tonos cálidos) en el cabello que ha sido aclarado antes de re-oscurecer — evitando resultados planos, opacos o verdosos", "Rellenar áreas delgadas en el cuero cabelludo para simular densidad del cabello", "Añadir proteína al cabello extremadamente dañado antes del color químico", "Cubrir temporalmente la cutícula para mejorar el brillo"], correct: 0, explanation: "When going from very light (bleached) back to darker hair, the missing warm contributing pigment must be restored first with a color filler. Without filling, the result can appear flat, dull, green, or drain quickly — because the warm 'backbone' is absent." },
  { id: 374, question: "Hair that has been colored with a permanent color should not be re-colored over the same section again for at least:", question_es: "El cabello que ha sido coloreado con un color permanente no debe volver a colorearse en la misma sección nuevamente durante al menos:", options: ["4–6 weeks (coinciding with the normal regrowth cycle), with retouches applied only to new growth", "48 hours to allow the color to fully oxidize", "72 hours minimum", "It can be re-colored anytime without restriction"], options_es: ["4–6 semanas (coincidiendo con el ciclo normal de nuevo crecimiento), con los retoques aplicados solo al nuevo crecimiento", "48 horas para permitir que el color se oxide completamente", "Mínimo 72 horas", "Puede volver a colorearse en cualquier momento sin restricción"], correct: 0, explanation: "Permanent color retouches should be applied every 4-6 weeks as new growth emerges. Re-coloring over previously processed hair (overlapping) with each service causes progressive damage and can lead to breakage." },
  { id: 375, question: "The 'law of color' in hair coloring states that:", question_es: "La 'ley del color' en la coloración del cabello establece que:", options: ["Mixing equal parts of two complementary colors produces a neutral (brown or gray) result; mixing primaries produces secondaries; and color on color follows predictable outcomes", "Hair color always processes faster on warm days", "Lighter colors always dominate darker colors when mixed", "A color can only be deposited, never lightened, on previously colored hair"], options_es: ["Mezclar partes iguales de dos colores complementarios produce un resultado neutro (marrón o gris); mezclar primarios produce secundarios; y color sobre color sigue resultados predecibles", "El color del cabello siempre procesa más rápido en días cálidos", "Los colores más claros siempre dominan a los más oscuros cuando se mezclan", "Un color solo puede depositarse, nunca aclararse, en cabello previamente colorido"], correct: 0, explanation: "The law of color provides predictable mixing outcomes: primaries mix to make secondaries; complementary colors neutralize each other. Understanding these laws allows colorists to predict results and correct color problems systematically." },
  { id: 376, question: "Hair color must never be applied to the scalp if:", question_es: "El color de cabello nunca debe aplicarse en el cuero cabelludo si:", options: ["The client shows a positive patch test (allergic reaction) result — service must not proceed", "The client has gray hair that is resistant to color", "The client has fine hair texture", "The appointment is a retouch rather than a virgin application"], options_es: ["El cliente muestra un resultado positivo de prueba de parche (reacción alérgica) — el servicio no debe continuar", "El cliente tiene canas que son resistentes al color", "El cliente tiene textura de cabello fino", "La cita es un retoque en lugar de una aplicación virgen"], correct: 0, explanation: "A positive patch test result (redness, swelling, blistering at the test site within 24-48 hours) indicates the client is allergic to color ingredients. Applying color to an allergic client can cause severe reactions including anaphylaxis. Service must be refused." },
  { id: 377, question: "Balayage is a hair coloring technique that:", question_es: "El balayage es una técnica de coloración del cabello que:", options: ["Freehand paints or sweeps lightener or color onto selected sections of hair for a natural, sun-kissed gradient effect without foil", "Applies uniform color throughout the entire hair shaft for full coverage", "Wraps color-saturated foils throughout the entire head for maximum lift", "Applies color only to the roots for a dark-to-light ombre effect"], options_es: ["Pinta o barre a mano alzada aclarante o color en secciones seleccionadas del cabello para un efecto degradado natural de beso de sol sin papel de aluminio", "Aplica color uniforme en todo el eje del cabello para cobertura completa", "Envuelve papeles de aluminio saturados de color en toda la cabeza para máximo levantamiento", "Aplica color solo en las raíces para un efecto ombre de oscuro a claro"], correct: 0, explanation: "Balayage (from French 'to sweep') is a freehand lightening technique where color or lightener is painted/swept onto sections of hair without foil. It creates a natural-looking, sun-kissed gradient that grows out more gracefully than traditional highlights." },
  { id: 378, question: "Traditional foil highlighting uses foil to:", question_es: "El resaltado con papel de aluminio tradicional usa el papel de aluminio para:", options: ["Isolate specific sections of hair, trapping heat to accelerate lightening and preventing the lightener from contacting surrounding hair", "Hold the hair in place while the colorist cuts it", "Reflect UV light onto the hair to accelerate oxidation", "Protect the scalp from direct contact with lightener"], options_es: ["Aislar secciones específicas del cabello, atrapando calor para acelerar el aclarado y evitando que el aclarante contacte el cabello circundante", "Mantener el cabello en su lugar mientras el colorista lo corta", "Reflejar la luz UV en el cabello para acelerar la oxidación", "Proteger el cuero cabelludo del contacto directo con el aclarante"], correct: 0, explanation: "Foils isolate specific sections of hair (highlights or lowlights), keeping the lightener/color from touching adjacent hair. The foil also traps heat, which can speed up processing. Foil highlights allow precise control over placement, pattern, and intensity." },
  { id: 379, question: "An 'ombre' color technique creates:", question_es: "Una técnica de color 'ombre' crea:", options: ["A gradient effect where hair transitions from one color (typically darker at roots) to another (lighter at ends)", "Uniform color throughout the entire hair shaft", "Multiple highlight streaks throughout the hair", "A solid block of color at the tips only"], options_es: ["Un efecto degradado donde el cabello hace transición de un color (típicamente más oscuro en las raíces) a otro (más claro en las puntas)", "Color uniforme en todo el eje del cabello", "Múltiples mechas a través del cabello", "Un bloque sólido de color solo en las puntas"], correct: 0, explanation: "Ombre (from French 'shaded') creates a gradient transition — usually darker at the roots blending to lighter at the ends. The blend can be subtle or dramatic. 'Sombre' (soft ombre) is a more subtle, blended version of the ombre technique." },
  { id: 380, question: "Color correction services are performed when:", question_es: "Los servicios de corrección de color se realizan cuando:", options: ["A previous color service produced an unwanted result (too dark, too light, wrong tone, color banding) that must be fixed", "A client wants to maintain their existing color at a retouch appointment", "A client is having their hair colored for the first time", "A client wants to refresh their color between appointments with a color gloss"], options_es: ["Un servicio de color anterior produjo un resultado no deseado (demasiado oscuro, demasiado claro, tono incorrecto, bandas de color) que debe corregirse", "Un cliente quiere mantener su color existente en una cita de retoque", "Un cliente se está coloreando el cabello por primera vez", "Un cliente quiere refrescar su color entre citas con un gloss de color"], correct: 0, explanation: "Color correction addresses problems from previous color services: unwanted tones (brassiness, too ash, too red), uneven color (banding, patchiness), hair that is too dark or too light, or incompatible color history. It is often a multi-step, multi-appointment process." },
  { id: 381, question: "When a client wants to go from very dark (Level 2 black) hair to very light (Level 9 blonde), which statement is true?", question_es: "Cuando un cliente quiere pasar de cabello muy oscuro (Nivel 2 negro) a muy claro (Nivel 9 rubio), ¿cuál enunciado es verdadero?", options: ["This is typically a multi-session process requiring multiple rounds of bleaching and conditioning — attempting to achieve it in one session risks severe damage and breakage", "This can safely be achieved in a single appointment using 40-volume developer and permanent color", "High-lift color mixed with 30-volume developer achieves this in one step on most clients", "It is not possible to go from black to blonde using professional color — only bleach powder works"], options_es: ["Esto es típicamente un proceso de múltiples sesiones que requiere varias rondas de aclarado y acondicionamiento — intentar lograrlo en una sola sesión arriesga daño severo y rotura", "Esto se puede lograr de forma segura en una sola cita usando revelador de 40 volúmenes y color permanente", "El color de alto levantamiento mezclado con revelador de 30 volúmenes logra esto en un solo paso en la mayoría de los clientes", "No es posible ir de negro a rubio usando color profesional — solo funciona el polvo decolorante"], correct: 0, explanation: "Going from Level 2 (black) to Level 9 (very light blonde) requires 7 levels of lift — far more than any single chemical process can safely achieve. Multiple bleaching sessions with conditioning treatments between are required to protect hair integrity." },
]

let out = readFileSync(FILE, 'utf8')
out += cwQ.map(q => fmt(q, cwT, cwTes)).join('\n') + '\n'
out += '\n// ─── HAIRCOLORING (ids 337–404) ──────────────────────────────────────────────\n'
out += hcQ.map(q => fmt(q, hcT, hcTes)).join('\n') + '\n'
writeFileSync(FILE, out, 'utf8')
console.log(`Appended ${cwQ.length} Chemical Waving (ids ${cwQ[0].id}–${cwQ[cwQ.length-1].id}) + ${hcQ.length} Haircoloring (ids ${hcQ[0].id}–${hcQ[hcQ.length-1].id})`)
